// ByteRxFifo.v -- DROP-IN replacement for the HDL-Coder-generated ByteRxFifo
// (modem/byte_rxfifo_overlay.m, 64-deep register FIFO). v4 (BRAM + registered write-through bypass).
//
// WHY (2026-08-27, sim-repro campaign E9): the generated FIFO is 64 words deep,
// sized for the K5 byte rate (16 words/frame x 212 fps -> "~19 ms of stall").
// At f1536 (191 words/frame x 1245 fps) 64 words cover only ~0.25 ms; the
// axi_dmac S2MM inter-transfer backpressure (once per -M transfer, 0.25-2 ms,
// tail to ~16 ms) overflows it and truncates one frame per transfer = the
// forward "boundary comb" (84 % of forward loss). Reproduced on captured air
// data with a periodic byte_rx_ready stall model.
//
// SAME external contract as the generated module: the 4-stage ready /
// stateControl delay chains, enqueue on every `tog` edge, dequeue on
// valid && ready_1, valid gated by the f1536 SOF-prime guard (ready_1 high
// for >= 6 cycles), full = drop OLDEST + count (ovf -> AXI 0x1B0), bypass
// outputs hold the last value while stateControl is low.
//
// v2 storage: a true simple-dual-port synchronous-read RAM (one write port,
// ONE registered read address, no reset on the array or its data output) so
// Vivado maps it to RAMB36 (v1 read two addresses inside the async-reset
// block -> "Infeasible ram_style=block", fell to LUTRAM, rejected). The read
// address is the NEXT-cycle head (`rd_next`), so the read register always
// holds the head word; `valid` uses a one-cycle-delayed write pointer so a
// word is presented only after the RAM read can see it. Net effect: +2 clk
// latency at the empty->non-empty edge, otherwise identical behaviour.
// Gated in Verilator (byte-exact no-stall stream vs the original; stall
// sweep) before injection into a build.
`timescale 1 ns / 1 ns
module ByteRxFifo #(parameter DEPTH = 4096, parameter AW = 12)
          (clk, reset, enb, word, tog, wLast, wFirst, ready,
           outWord, valid, outLast, outFirst, ovf);
  input          clk;
  input          reset;
  input          enb;
  input  [63:0]  word;   // ufix64
  input          tog;
  input          wLast;
  input          wFirst;
  input          ready;
  output [63:0]  outWord;  // ufix64
  output         valid;
  output         outLast;
  output         outFirst;
  output [31:0]  ovf;      // uint32

  // ---- generated-module delay chains (kept verbatim) ----
  reg [3:0] delayMatch1_reg;   // stateControl pipeline
  reg [3:0] delayMatch_reg;    // ready pipeline
  wire stateControl_2 = delayMatch1_reg[3];
  wire enb_gated      = stateControl_2 && enb;
  wire ready_1        = delayMatch_reg[3];
  always @(posedge clk or posedge reset)
    if (reset) delayMatch1_reg <= 4'b0;
    else if (enb) delayMatch1_reg <= {delayMatch1_reg[2:0], 1'b1};
  always @(posedge clk or posedge reset)
    if (reset) delayMatch_reg <= 4'b0;
    else if (enb) delayMatch_reg <= {delayMatch_reg[2:0], ready};

  // ---- control state (async reset, small) ----
  reg [AW-1:0] wr, rd, wr_q;    // write ptr, read ptr (head), write ptr delayed one cycle
  reg          prev;            // last tog
  reg [31:0]   ovfCnt;
  reg [7:0]    rdyRun;          // ready_1 continuous-high run length (sat 255)

  wire push     = (tog != prev);
  wire [AW-1:0] wr_p1 = wr + 1'b1;
  wire [AW-1:0] rd_p1 = rd + 1'b1;
  // head word is readable once the delayed write pointer has passed it
  wire nonempty = (rd != wr_q);
  wire valid_i  = nonempty && (rdyRun >= 8'd6);
  wire pop      = valid_i && ready_1;
  // full = the push would land on the head: drop the OLDEST (advance rd past it)
  wire [AW-1:0] rd_after_pop = pop ? rd_p1 : rd;
  wire drop     = push && (wr_p1 == rd_after_pop);
  wire [AW-1:0] rd_next = drop ? (rd_after_pop + 1'b1) : rd_after_pop;

  // ---- storage: simple dual port, clock-only, no reset (BRAM) ----
  (* ram_style = "block" *) reg [71:0] mem [0:DEPTH-1];   // {6'b0, wFirst, wLast, word}
  reg [71:0] rdata;
  always @(posedge clk)
    if (enb_gated && push) mem[wr] <= {6'b0, wFirst, wLast, word};
  // v3: write-through bypass. When the incoming word is written to the very slot the
  // read port fetches in the same cycle (empty FIFO, push to the head), a Xilinx SDP
  // block RAM returns UNDEFINED data for that cross-port collision (RTL sim returns the
  // old contents and the next re-read heals it). Forward the write data instead so the
  // read register never depends on a collided BRAM read. Silicon-only hazard, candidate
  // for the zero-delivery seen on 2026-08-27 attempt 3.
  // v4: the bypass is a SEPARATE registered path, muxed AFTER the BRAM output register, so
  // the RAM read stays a pure `rdata_mem <= mem[addr]` (v3 put the mux inside the read
  // assignment and Vivado dropped to LUTRAM: BRAM tiles back to 59, WNS -0.047 ns).
  wire wr_hits_read = enb_gated && push && (wr == rd_next);
  reg  [71:0] rdata_mem;
  reg  [71:0] byp_data;
  reg         byp_sel;
  always @(posedge clk)
    if (enb_gated) rdata_mem <= mem[rd_next];
  always @(posedge clk or posedge reset)
    if (reset) begin byp_sel <= 1'b0; byp_data <= 72'd0; end
    else if (enb_gated) begin byp_sel <= wr_hits_read; byp_data <= {6'b0, wFirst, wLast, word}; end
  always @* rdata = byp_sel ? byp_data : rdata_mem;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      wr <= {AW{1'b0}}; rd <= {AW{1'b0}}; wr_q <= {AW{1'b0}}; prev <= 1'b0;
      ovfCnt <= 32'd0; rdyRun <= 8'd0;
    end else if (enb_gated) begin
      prev <= tog;
      wr_q <= wr;
      if (push) wr <= wr_p1;
      rd <= rd_next;
      if (drop) ovfCnt <= (ovfCnt == 32'hFFFFFFFF) ? ovfCnt : ovfCnt + 32'd1;
      if (ready_1) rdyRun <= (rdyRun == 8'd255) ? rdyRun : rdyRun + 8'd1;
      else         rdyRun <= 8'd0;
    end
  end

  // ---- outputs with the generated bypass semantics (hold last when !stateControl_2) ----
  reg [63:0] outWord_last; reg valid_last, outLast_last, outFirst_last; reg [31:0] ovf_last;
  always @(posedge clk or posedge reset)
    if (reset) begin outWord_last <= 64'd0; valid_last <= 1'b0; outLast_last <= 1'b0; outFirst_last <= 1'b0; ovf_last <= 32'd0; end
    else if (enb_gated) begin outWord_last <= outWord; valid_last <= valid; outLast_last <= outLast; outFirst_last <= outFirst; ovf_last <= ovf; end
  assign outWord  = stateControl_2 ? rdata[63:0] : outWord_last;
  assign valid    = stateControl_2 ? valid_i     : valid_last;
  assign outLast  = stateControl_2 ? rdata[64]   : outLast_last;
  assign outFirst = stateControl_2 ? rdata[65]   : outFirst_last;
  assign ovf      = stateControl_2 ? ovfCnt      : ovf_last;
endmodule  // ByteRxFifo (BRAM drop-in v4, injected by rxfifo_inject.sh)
